def choose_move(observation):
    def gv(key, default=None):
        return observation.get(key, default) if hasattr(observation, "get") else default

    def pos(v, default=(0, 0)):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            return v[0], v[1]
        return default

    def clamp_step(a, b):
        if b > a:
            return 1
        if b < a:
            return -1
        return 0

    def dist(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def best_move_toward(start, target):
        return [clamp_step(start[0], target[0]), clamp_step(start[1], target[1])]

    def pick_nearest(start, items):
        best = None
        best_d = None
        for it in items:
            p = pos(it, None)
            if p is None:
                continue
            d = dist(start, p)
            if best is None or d < best_d:
                best = p
                best_d = d
        return best

    def pick_farthest(start, items):
        best = None
        best_d = None
        for it in items:
            p = pos(it, None)
            if p is None:
                continue
            d = dist(start, p)
            if best is None or d > best_d:
                best = p
                best_d = d
        return best

    sx, sy = pos(gv("self_position", (0, 0)))
    ox, oy = pos(gv("opponent_position", (sx, sy)))
    self_pos = (sx, sy)
    opp_pos = (ox, oy)
    env = gv("environment_name", "resource_collection")
    role = gv("self_role", "")

    width = gv("grid_width", gv("width", 0))
    height = gv("grid_height", gv("height", 0))

    resources = gv("resources") or gv("resource_positions") or []
    unclaimed = gv("unclaimed_cells") or gv("neutral_cells") or []
    enemy_territory = gv("opponent_territory") or gv("enemy_territory") or []
    threats = gv("enemy_positions") or gv("opponents") or []

    if isinstance(threats, dict):
        threats = list(threats.values())

    if env == "pursuit_evasion":
        if role == "pursuer" or role == 1:
            tgt = opp_pos
            if isinstance(threats, list) and threats:
                p = pick_nearest(self_pos, threats)
                if p is not None:
                    tgt = p
            return best_move_toward(self_pos, tgt)
        corners = []
        if width and height:
            corners = [(0, 0), (0, height - 1), (width - 1, 0), (width - 1, height - 1)]
        else:
            corners = [(-10, -10), (-10, 10), (10, -10), (10, 10)]
        tgt = pick_farthest(opp_pos, corners) or pick_farthest(self_pos, corners) or self_pos
        return best_move_toward(self_pos, tgt)

    if env == "territory_control":
        target_sets = []
        if unclaimed:
            target_sets.append(unclaimed)
        if enemy_territory:
            target_sets.append(enemy_territory)
        if resources:
            target_sets.append(resources)
        for pool in target_sets:
            tgt = pick_nearest(self_pos, pool)
            if tgt is not None:
                move = best_move_toward(self_pos, tgt)
                if move != [0, 0]:
                    return move
        if width and height:
            center = (width // 2, height // 2)
            return best_move_toward(self_pos, center)
        return [0, 0]

    if resources:
        tgt = pick_nearest(self_pos, resources)
        if tgt is not None:
            return best_move_toward(self_pos, tgt)

    if isinstance(threats, list) and threats:
        tgt = pick_farthest(opp_pos, threats)
        if tgt is not None:
            return best_move_toward(self_pos, tgt)

    return best_move_toward(self_pos, opp_pos)

